,"display":{"rawSum":68,"itemsUsed":24,"itemMean":2.8333333333333335,"pomp":45.833333333333336}}},"overallScore":null,"normReference":null}}]$fixtures$::jsonb;
  frozen jsonb; expected jsonb; n4 uuid; blocked boolean;
  partner uuid; client uuid; campaign uuid; ca uuid; other uuid; other_ca uuid;
BEGIN
  config := public.get_ipip_neo_120_delivery(aid,NULL);
  IF NOT EXISTS(SELECT 1 FROM public.assessments WHERE id=aid AND status='draft' AND scoring_profile='ipip_neo_120_v1')
    OR EXISTS(SELECT 1 FROM public.standardized_assessment_forms WHERE assessment_id=aid AND activation_ready) THEN RAISE EXCEPTION 'Draft/activation policy failed'; END IF;
  IF (SELECT count(*) FROM public.items WHERE id::text IN(SELECT value#>>'{}' FROM jsonb_each(config->'items')))<>120
    OR (SELECT count(DISTINCT content_hash) FROM public.items WHERE id::text IN(SELECT value#>>'{}' FROM jsonb_each(config->'items')))<>120
    OR (SELECT count(*) FROM public.factors WHERE id::text IN(SELECT value->>'factorId' FROM jsonb_each(config->'facets')))<>30
    OR (SELECT count(*) FROM public.constructs WHERE id::text IN(SELECT value->>'constructId' FROM jsonb_each(config->'facets')))<>30
    OR (SELECT count(*) FROM public.dimensions WHERE id::text IN(SELECT value#>>'{}' FROM jsonb_each(config->'dimensions')))<>5 THEN RAISE EXCEPTION 'Canonical import count failed'; END IF;
  IF has_table_privilege('anon','public.participant_instrument_results','SELECT')
    OR has_table_privilege('authenticated','public.participant_instrument_results','SELECT')
    OR has_function_privilege('anon','public.persist_ipip_neo_120_result(uuid,jsonb)','EXECUTE')
    OR has_function_privilege('authenticated','public.persist_ipip_neo_120_result(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Private result grants failed'; END IF;
  SELECT jsonb_agg(jsonb_build_object('position',n,'itemId',config->'items'->>('q'||lpad(n::text,3,'0')),'itemVersion',1,'contentHash',config->'itemContentHashes'->>('q'||lpad(n::text,3,'0')),'purpose','construct','countsTowardScore',true) ORDER BY n) INTO frozen FROM generate_series(1,120) n;
  FOR fixture IN SELECT value FROM jsonb_array_elements(fixtures) LOOP
    INSERT INTO public.participant_sessions(assessment_id,status,is_internal) VALUES(aid,'completed',true) RETURNING id INTO sid;
    INSERT INTO public.participant_section_forms(session_id,section_id,assembly_seed,assembler_version,form_code,entries,entry_count,authoring_revision)
      VALUES(sid,section_key,sid::text||':'||section_key::text,'form-assembler@2',config->>'formVersion',frozen,120,public.get_delivery_authoring_revision(aid));
    IF NOT EXISTS(SELECT 1 FROM public.participant_section_forms f WHERE f.session_id=sid AND f.entries=frozen AND f.entry_count=120) THEN RAISE EXCEPTION 'Freeze/resume failed'; END IF;
    INSERT INTO public.participant_responses(session_id,section_id,item_id,response_value)
      SELECT sid,section_key,(config->'items'->>key)::uuid,(value#>>'{}')::integer FROM jsonb_each(fixture->'responses');
    expected:=fixture->'result';
    PERFORM public.persist_ipip_neo_120_result(sid,expected);
    PERFORM public.persist_ipip_neo_120_result(sid,expected);
    IF NOT EXISTS(SELECT 1 FROM public.participant_instrument_results WHERE session_id=sid AND result=expected)
      OR (SELECT count(*) FROM public.participant_scores WHERE session_id=sid)<>30
      OR EXISTS(SELECT 1 FROM public.participant_scores WHERE session_id=sid AND (metric<>'personality_pomp' OR percentile IS NOT NULL OR norm_group_id IS NOT NULL OR norm_version IS NOT NULL))
      OR EXISTS(SELECT 1 FROM public.participant_sessions WHERE id=sid AND (composite_score IS NOT NULL OR composite_method IS NOT NULL)) THEN RAISE EXCEPTION 'Persist/retry/no-norm/overall failed: %',fixture->>'id'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_each(config->'facets') facet JOIN public.participant_scores s ON s.factor_id=(facet.value->>'factorId')::uuid AND s.session_id=sid
      WHERE abs(s.raw_score-(expected->'facets'->facet.key->'native'->>'rawSum')::numeric)>0.000001 OR abs(s.scaled_score-(expected->'facets'->facet.key->'display'->>'pomp')::numeric)>0.000001) THEN RAISE EXCEPTION 'Native/display score mismatch'; END IF;
    BEGIN
      UPDATE public.participant_instrument_results SET result='{}' WHERE session_id=sid;
      RAISE EXCEPTION 'Result edit was permitted';
    EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL; END;
    blocked:=false;
    BEGIN PERFORM public.persist_ipip_neo_120_result(sid,jsonb_set(expected,'{overallScore}','10'::jsonb)); EXCEPTION WHEN raise_exception THEN blocked:=true; END;
    IF NOT blocked THEN RAISE EXCEPTION 'Changed retry was permitted'; END IF;
  END LOOP;
  INSERT INTO public.participant_sessions(assessment_id,status,is_internal) VALUES(aid,'completed',true) RETURNING id INTO sid;
  INSERT INTO public.participant_section_forms(session_id,section_id,assembly_seed,assembler_version,form_code,entries,entry_count,authoring_revision)
    VALUES(sid,section_key,sid::text||':'||section_key::text,'form-assembler@2',config->>'formVersion',frozen,120,public.get_delivery_authoring_revision(aid));
  blocked:=false;
  BEGIN PERFORM public.persist_ipip_neo_120_result(sid,fixtures->0->'result'); EXCEPTION WHEN raise_exception THEN blocked:=true; END;
  IF NOT blocked OR EXISTS(SELECT 1 FROM public.participant_instrument_results WHERE session_id=sid) OR EXISTS(SELECT 1 FROM public.participant_scores WHERE session_id=sid) THEN RAISE EXCEPTION 'Incomplete response gate failed'; END IF;
  BEGIN UPDATE public.items SET stem='IPIP acceptance forbidden edit' WHERE id=(config->'items'->>'q001')::uuid; RAISE EXCEPTION 'Item edit allowed'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN UPDATE public.assessments SET status='active' WHERE id=aid; RAISE EXCEPTION 'Activation allowed'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN DELETE FROM public.assessment_section_items s WHERE s.section_id=section_key AND item_id=(config->'items'->>'q001')::uuid; RAISE EXCEPTION 'Short form allowed'; EXCEPTION WHEN check_violation THEN NULL; END;
  BEGIN INSERT INTO public.factors(name,slug,dimension_id) VALUES('Forbidden IPIP facet','ipip-hosted-forbidden-'||gen_random_uuid(),(config->'dimensions'->>'N')::uuid); RAISE EXCEPTION 'Extra facet allowed'; EXCEPTION WHEN check_violation THEN NULL; END;
  INSERT INTO public.partners(name,slug) VALUES('IPIP rollback-only acceptance','ipip-acceptance-'||gen_random_uuid()) RETURNING id INTO partner;
  INSERT INTO public.clients(name,slug,partner_id) VALUES('IPIP rollback-only acceptance','ipip-acceptance-'||gen_random_uuid(),partner) RETURNING id INTO client;
  INSERT INTO public.campaigns(title,slug,client_id,partner_id,status,is_internal) VALUES('IPIP rollback-only acceptance','ipip-acceptance-'||gen_random_uuid(),client,partner,'draft',true) RETURNING id INTO campaign;
  INSERT INTO public.campaign_assessments(campaign_id,assessment_id) VALUES(campaign,aid) RETURNING id INTO ca;
  n4:=(config->'facets'->'N4'->>'factorId')::uuid;
  BEGIN
    INSERT INTO public.campaign_assessment_factors(campaign_assessment_id,factor_id) VALUES(ca,n4);
    SET CONSTRAINTS ALL IMMEDIATE;
    RAISE EXCEPTION 'Partial selection allowed';
  EXCEPTION WHEN check_violation THEN NULL; END;
  INSERT INTO public.campaign_assessment_factors(campaign_assessment_id,factor_id) SELECT ca,(value->>'factorId')::uuid FROM jsonb_each(config->'facets');
  SET CONSTRAINTS ALL IMMEDIATE;
  PERFORM public.get_ipip_neo_120_delivery(aid,campaign);
  INSERT INTO public.assessments(title,slug) VALUES('IPIP other rollback-only assessment','ipip-other-'||gen_random_uuid()) RETURNING id INTO other;
  INSERT INTO public.campaign_assessments(campaign_id,assessment_id) VALUES(campaign,other) RETURNING id INTO other_ca;
  BEGIN
    UPDATE public.campaign_assessment_factors SET campaign_assessment_id=other_ca WHERE campaign_assessment_id=ca AND factor_id=n4;
    RAISE EXCEPTION 'Moving facet allowed';
  EXCEPTION WHEN check_violation THEN NULL; END;
  IF (SELECT count(*) FROM public.campaign_assessment_factors WHERE campaign_assessment_id=ca)<>30 THEN RAISE EXCEPTION 'Full selection corrupted'; END IF;
END $acceptance$;
ROLLBACK;
SELECT jsonb_build_object('acceptance','passed: 3 golden scoring cases, frozen form, exact canonical content, retry, privacy, no overall/norm, incomplete response gate, immutable draft and campaign subset/move guards',
  'assessment',(SELECT jsonb_build_object('id',id,'status',status,'scoringProfile',scoring_profile) FROM public.assessments WHERE id='741663b2-fbc1-56fe-a0ed-c9bb521e18b6'),
  'activationReady',(SELECT activation_ready FROM public.standardized_assessment_forms WHERE assessment_id='741663b2-fbc1-56fe-a0ed-c9bb521e18b6'),
  'sessionsAfterRollback',(SELECT count(*) FROM public.participant_sessions),
  'instrumentResultsAfterRollback',(SELECT count(*) FROM public.participant_instrument_results),
  'databaseChecksOnly',true,'browserAndPdfAcceptance',false) AS verification;
